4.16 Gestion des erreurs

lire_positif &lt;- function(x) {
  tryCatch(
    {
      if (x &lt; 0) stop("La valeur doit être positive")
      sqrt(x)
    },
    error = function(e) {
      message("Erreur : ", e$message)
      NA_real_
    }
  )
}
lire_positif(9)

#&gt; [1] 3

lire_positif(-1)

#&gt; [1] NA

