11.16 Exemple minimal exécutable (concept)

library(shiny)
library(ggplot2)

ui &lt;- fluidPage(
  titlePanel("Histo mtcars"),
  selectInput("var", "Variable", choices = names(mtcars)),
  plotOutput("hist")
)

server &lt;- function(input, output, session) {
  output$hist &lt;- renderPlot({
    ggplot(mtcars, aes(.data[[input$var]])) +
      geom_histogram(bins = 15, fill = "#1a5276", color = "white") +
      theme_minimal()
  })
}

